'use strict';
const main=document.getElementById('main'),dialog=document.getElementById('flow-dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const labels={available:'Available',requested:'Requested',held:'Held',booked:'Booked'};
let backend,selected='B09',view='vendor',refreshTimer,busy=false;
function notify(text){document.getElementById('trial-status').textContent=text;}
function panel(title,text){main.innerHTML=`<section class="intro"><div><div class="eyebrow">STALLSLOT / PRIVATE TRIAL</div><h1>${title}</h1><p class="admin-note">${text}</p></div></section>`;}
function showLogin(message='Sign in with the account provided for your trial.'){clearInterval(refreshTimer);document.getElementById('role-label').textContent='Private workspace';document.getElementById('account-actions').hidden=true;panel('Your market. <em>Your workspace.</em>',esc(message));main.insertAdjacentHTML('beforeend',`<form id="login-form" class="ticket login-card"><div class="ticket-body"><h2>Welcome back.</h2><label class="field"><span>Email</span><input type="email" name="email" autocomplete="username" required></label><label class="field"><span>Password</span><input type="password" name="password" autocomplete="current-password" required></label><p class="form-error" id="login-error" role="alert"></p><button class="primary">Sign in ↗</button><p class="fine">Invitation only. Need access or a password reset? Contact Krishna through your existing email conversation.</p></div></form>`);document.getElementById('login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {error}=await backend.client.auth.signInWithPassword({email:e.target.email.value.trim(),password:e.target.password.value});if(error)throw Error('Sign-in failed. Check your email and password.');await startSession();}catch(err){document.getElementById('login-error').textContent=err.message;}finally{b.disabled=false;}};}
async function startSession(){try{await backend.load();document.getElementById('account-actions').hidden=false;view=backend.role()==='organiser'?'admin':'vendor';render();clearInterval(refreshTimer);refreshTimer=setInterval(()=>sync(),20000);}catch(err){panel('Access needed.',esc(err.message));main.insertAdjacentHTML('beforeend','<button class="small-button" id="try-login">Use another account</button>');document.getElementById('try-login').onclick=async()=>{await backend.client.auth.signOut({scope:'local'});showLogin();};}}
async function sync(){if(busy||dialog.open||document.hidden)return;try{await backend.refresh();render();notify('Availability updated.');}catch{notify('Could not refresh. Check your connection before making changes.');}}
function position(s){const sides=[25,34,43,59,68,77];if(s.row===0)return[9+s.col*14,12];if(s.row===1)return[6,sides[s.col]];if(s.row===2)return[84,sides[s.col]];return[[7,20,33,57,70,83][s.col],88];}
function render(){const e=backend.event(),organiser=backend.role()==='organiser';document.getElementById('trial-mode').textContent=e.is_test?'PRIVATE PRACTICE EVENT · SAVED SAMPLE BOOKINGS · NO REAL PAYMENTS':'PRIVATE EVENT · PAYMENTS CHECKED BY ORGANISER';document.getElementById('role-label').textContent=organiser?'Organiser account':'Vendor account';document.getElementById('organiser-button').hidden=!organiser;document.getElementById('map-button').classList.toggle('active',view==='vendor');document.getElementById('organiser-button').classList.toggle('active',view==='admin');if(view==='admin'&&organiser)renderAdmin();else renderMap();}
function renderMap(){const all=backend.list(),s=backend.get(selected),own=all.find(x=>x.mine),e=backend.event();const canRequest=backend.role()==='vendor'&&e.is_open&&!own&&s.status==='available';main.innerHTML=`<section class="intro"><div><div class="eyebrow">${esc(e.name)} / ${e.is_test?'Fictional trial event':'Private event'}</div><h1>Find your <em>little corner.</em></h1><p class="admin-note">${e.is_open?'Requests are open. Your place is confirmed only after organiser approval and deposit review.':'Requests are currently closed. You can explore the layout.'}</p></div></section>${own?`<section class="own-booking"><strong>Your stall: ${own.id} · ${labels[own.status]}</strong><span>${esc(own.business)} · Reference ${esc(own.bookingId)}</span><p>${own.status==='booked'?'Your stall is confirmed.':own.status==='held'?'Your request is approved. Contact the organiser about the next step.':'Your request is saved and awaiting review.'} ${e.is_test?'This practice event does not collect money.':''}</p></section>`:''}<div class="workspace"><section aria-label="Stall map"><div class="map-card"><div class="map-toolbar"><div class="map-title">Choose your space <span>${all.filter(x=>x.status==='available').length} of ${all.length} available</span></div><button class="small-button" id="refresh-map">Refresh</button></div><div class="map-scroll"><div class="floorplan" role="group" aria-label="Interactive stall map"><span class="plan-stamp">COURTYARD / TRIAL</span><span class="north">N ↑</span><div class="zone-label zone-north">NORTH · BRANDS</div><div class="courtyard-space"><span class="eyebrow">THE HEART OF THE MARKET</span><strong>Open courtyard</strong><span>Space to browse, meet & gather.</span></div><div class="zone-label zone-food">SOUTH · FOOD & DRINK</div><div class="side-exit">← EXIT</div>${all.map(x=>{const [left,top]=position(x);return `<button class="stall side-${x.row} ${x.status} ${x.id===selected?'selected':''}" style="left:${left}%;top:${top}%" data-stall="${x.id}" aria-label="Stall ${x.id}, ${labels[x.status]}" aria-pressed="${x.id===selected}"><strong>${x.id}</strong><small>${x.status==='available'?money(x.price):labels[x.status]}</small></button>`;}).join('')}<div class="entry">↑ IN</div></div></div><div class="map-bottom"><div class="legend">${Object.keys(labels).map(k=>`<span><i class="swatch ${k}" aria-hidden="true"></i>${labels[k]}</span>`).join('')}</div></div></div></section><aside><article class="ticket"><div class="ticket-head"><div class="eyebrow">Selected space</div><div class="ticket-identity"><span class="ticket-number">${s.id}</span><span class="ticket-status">${labels[s.status]}</span></div></div><div class="ticket-body"><h2>${s.power?'A taste of the market.':'A place for your brand.'}</h2><dl class="details-grid"><div><dt>Size</dt><dd>${s.size}</dd></div><div><dt>Location</dt><dd>${s.zone}</dd></div><div><dt>Electricity</dt><dd>${s.power?'Included':'Not included'}</dd></div></dl><div class="price-row"><strong>${money(s.price)}</strong><span>${e.is_test?'sample event price':'for the event'}</span></div><button class="primary" id="request-button" ${canRequest?'':'disabled'}>Request this stall ↗</button><p class="fine">${backend.role()==='organiser'?'Vendor accounts submit requests.':own?'You already have a saved request for this event.':!e.is_open?'The organiser has closed requests.':'One active request per vendor. No payment is collected here.'}</p></div></article></aside></div>`;document.querySelectorAll('[data-stall]').forEach(b=>b.onclick=()=>{selected=b.dataset.stall;renderMap();document.querySelector(`[data-stall="${selected}"]`).focus();});document.getElementById('request-button').onclick=()=>requestDialog(s);document.getElementById('refresh-map').onclick=sync;}
function modal(title,body){document.getElementById('dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="close" id="close-dialog" aria-label="Close dialog">×</button></div>${body}</div>`;document.getElementById('close-dialog').onclick=()=>{if(!busy)dialog.close();};if(!dialog.open)dialog.showModal();}
async function submit(form,work,success){if(busy)return;busy=true;form.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);try{const savedMessage=await work();dialog.close();render();notify(savedMessage||success);}catch(err){form.querySelector('[role="alert"]').textContent=err.message||'Could not save. Refresh and check your request before trying again.';try{await backend.refresh();}catch{} }finally{busy=false;form.querySelectorAll('button,input,select').forEach(x=>x.disabled=false);}}
function requestDialog(s){const categories=s.power?['Food & drink']:['Fashion','Accessories','Art & craft','Home & lifestyle'];modal('Make yourself at home.',`<p class="dialog-sub">Stall ${s.id} · ${money(s.price)}. ${backend.event().is_test?'Use fictional names for this practice event.':''}</p><form id="request-form"><label class="field"><span>Contact name</span><input name="name" required minlength="2" maxlength="60" autocomplete="name"></label><label class="field"><span>Business name</span><input name="business" required minlength="2" maxlength="80" autocomplete="organization"></label><label class="field"><span>What do you sell?</span><select name="category">${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><p class="fine">Your account and these details are visible to your event organiser. Other vendors can see availability, but cannot see your contact or business details.</p><p class="form-error" role="alert"></p><button class="primary">Send request ↗</button></form>`);document.getElementById('request-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));submit(e.target,async()=>{const r=await backend.request(s.id,data);if(r.refreshPending)return 'Request saved. Refresh to see the latest map.';},'Request saved. Awaiting organiser review.');};}
function renderAdmin(){const rows=backend.list().filter(s=>s.status!=='available');main.innerHTML=`<section class="intro"><div><div class="eyebrow">${esc(backend.event().name)} / ORGANISER</div><h1>Good markets. <em>Less admin.</em></h1><p class="admin-note">Review vendors, hold spaces, and record deposits you have checked. Changes are saved for this event.</p></div></section><section class="admin-panel"><div class="panel-head"><h2>Requests & bookings</h2><button class="small-button" id="refresh-admin">Refresh</button></div><div class="table-scroll"><table><thead><tr><th>Vendor</th><th>Stall</th><th>Status</th><th>Next step</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.business)}</strong><small>${esc(s.name)} · ${esc(s.category)}</small></td><td>${s.id}</td><td><span class="pill ${s.status}">${labels[s.status]}</span></td><td><div class="row-actions">${s.status==='requested'?`<button class="small-button emphasis" data-action="approve" data-id="${s.id}">Approve</button>`:s.status==='held'?`<button class="small-button emphasis" data-action="confirm" data-id="${s.id}">Check deposit</button>`:'Deposit recorded'}${['requested','held'].includes(s.status)?`<button class="small-button" data-action="release" data-id="${s.id}">${s.status==='requested'?'Decline':'Release'}</button>`:''}</div></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">No requests yet. Invite a vendor to try the map.</div>'}</div></section>`;document.getElementById('refresh-admin').onclick=sync;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actionDialog(b.dataset.id,b.dataset.action));}
function actionDialog(id,action){const s=backend.get(id),isTest=backend.event().is_test;modal(action==='approve'?'Approve this request?':action==='release'?'Release this space?':'Check the deposit.',`<p class="dialog-sub">${esc(s.business)} · stall ${id}</p><form id="action-form">${action==='confirm'?`<p>Expected deposit: <strong>${money(s.price/2)}</strong></p><label class="check-label"><input name="verified" type="checkbox" required><span>${isTest?'Simulate checking':'I have checked my bank or payment app and verified receipt of'} the ${money(s.price/2)} deposit.</span></label><p class="fine">${isTest?'Practice event. Do not send real money.':'StallSlot records your confirmation. It does not move money or verify payment automatically.'}</p>`:`<p>${action==='approve'?'The stall stays held for this vendor until you record the deposit.':'This frees the stall. The previous request remains in the event record. No email is sent.'}</p>`}<p class="form-error" role="alert"></p><button class="primary">${action==='approve'?'Approve & hold':action==='release'?'Release stall':'Confirm booking'} ↗</button></form>`);document.getElementById('action-form').onsubmit=e=>{e.preventDefault();const verified=e.target.elements.verified?.checked===true;submit(e.target,async()=>{const fresh=await backend.change(id,action,verified);if(!fresh)return 'Change saved. Refresh to see the latest status.';},'Change saved.');};}
dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
document.getElementById('map-button').onclick=()=>{view='vendor';render();};document.getElementById('organiser-button').onclick=()=>{view='admin';render();};
document.getElementById('sign-out').onclick=async()=>{if(busy)return;await backend.client.auth.signOut({scope:'local'});dialog.close();showLogin();notify('Signed out on this browser.');};
(async()=>{try{backend=window.createTrialBackend(window.STALLSLOT_CONFIG);backend.client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){dialog.close();showLogin('Your session has ended. Sign in to continue.');}});const {data:{session}}=await backend.client.auth.getSession();if(session)await startSession();else showLogin();}catch{panel('The trial is <em>getting ready.</em>','The private booking workspace is not connected yet. No requests can be submitted here until setup is complete.');main.insertAdjacentHTML('beforeend','<a class="small-button" href="/">Explore the public demo ↗</a>');}})();
